<?php
namespace AmitShaw\FCB;
defined('ABSPATH') || exit;
$search=self::input('search',$_GET); $status=self::input('filter_status',$_GET); $current=max(1,absint($_GET['paged'] ?? 1));
$records=Store::query($search,$status,$current);
?>
<div class="fcb-page-heading"><div><span class="fcb-eyebrow"><?php esc_html_e('FOLLOW UP WITH CONFIDENCE',self::DOMAIN); ?></span><h1><?php esc_html_e('Customer enquiries',self::DOMAIN); ?></h1><p><?php esc_html_e('See who requested a callback and whether you have responded.',self::DOMAIN); ?></p><p class="fcb-hint"><?php esc_html_e('Only submitted details are stored. Administrator access is required.',self::DOMAIN); ?></p></div><span class="fcb-status"><?php echo (int)$records['total']; ?> <?php esc_html_e('matching enquiries',self::DOMAIN); ?></span></div>
<?php if (!$live['inbox']) : ?><div class="fcb-inline-note"><?php esc_html_e('Local inbox storage is currently off. Previously saved requests remain available until deleted or expired. Enable storage in Privacy & Mail and publish to retain new enquiries.',self::DOMAIN); ?></div><?php endif; ?>
<?php if (isset($_GET['updated'])) : ?><div class="fcb-inline-note" role="status"><?php esc_html_e('Inbox updated.',self::DOMAIN); ?></div><?php endif; ?>
<section class="fcb-card-admin fcb-inbox-card">
<div class="fcb-inbox-toolbar"><form method="get"><input type="hidden" name="page" value="fcb-inbox"><label class="screen-reader-text" for="fcb-search"><?php esc_html_e('Search enquiries',self::DOMAIN); ?></label><input id="fcb-search" type="search" name="search" value="<?php echo esc_attr($search); ?>" placeholder="<?php esc_attr_e('Search name, contact or message…',self::DOMAIN); ?>"><label class="screen-reader-text" for="fcb-filter"><?php esc_html_e('Filter by status',self::DOMAIN); ?></label><select id="fcb-filter" name="filter_status"><option value=""><?php esc_html_e('All statuses',self::DOMAIN); ?></option value="new"<?php selected($status,'new'); ?>><?php esc_html_e('New',self::DOMAIN); ?></option value="contacted"<?php selected($status,'contacted'); ?>><?php esc_html_e('Contacted',self::DOMAIN); ?></option value="resolved"<?php selected($status,'resolved'); ?>><?php esc_html_e('Resolved',self::DOMAIN); ?></select><button class="fcb-button fcb-button-light"><?php esc_html_e('Filter',self::DOMAIN); ?></button></form>
<form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="fcb_inbox"><input type="hidden" name="mode" value="export"><input type="hidden" name="search" value="<?php echo esc_attr($search); ?>"><input type="hidden" name="filter_status" value="<?php echo esc_attr($status); ?>"><?php wp_nonce_field('fcb_inbox'); ?><button class="fcb-button fcb-button-light"><?php esc_html_e('Export filtered CSV',self::DOMAIN); ?> ↓</button></form></div>
<p class="fcb-hint"><?php esc_html_e('CSV exports contain customer details. Store and share them securely. Times are shown in the site timezone; exports use UTC.',self::DOMAIN); ?></p>
<?php if (!$records['rows']) : ?><div class="fcb-empty"><?php echo Widget::icon('chat'); ?><h2><?php esc_html_e('No enquiries here yet.',self::DOMAIN); ?></h2><p><?php esc_html_e('Accepted form submissions appear here when the inbox is enabled. Contact-button clicks never create enquiry records.',self::DOMAIN); ?></p></div>
<?php else : ?><div class="fcb-table-scroll"><table class="fcb-table"><thead><tr><th><?php esc_html_e('Customer & request',self::DOMAIN); ?></th><th><?php esc_html_e('Submitted',self::DOMAIN); ?></th><th><?php esc_html_e('Follow-up',self::DOMAIN); ?></th><th><?php esc_html_e('Actions',self::DOMAIN); ?></th></tr></thead><tbody>
<?php foreach ($records['rows'] as $r) : ?><tr><td><strong><?php echo esc_html($r['name'] ?: __('Name not provided',self::DOMAIN)); ?></strong><div class="fcb-contact-value"><?php echo esc_html($r['contact']); ?></div><?php if ($r['message']) : ?><p class="fcb-customer-message"><?php echo nl2br(esc_html($r['message'])); ?></p><?php endif; ?><details><summary><?php esc_html_e('Request details',self::DOMAIN); ?></summary><p><?php echo esc_html($r['submission_id']); ?><br><?php echo esc_html($r['channel']); ?><br><?php if ($r['source_url']) { echo '<a href="'.esc_url($r['source_url']).'" target="_blank" rel="noopener">'.esc_html($r['source_url']).'</a>'; } ?><br><?php echo $r['notification']==='accepted' ? esc_html__('Notification: accepted by transport; delivery unconfirmed.',self::DOMAIN) : ($r['notification']==='failed' ? esc_html__('Notification: transport failed. Request is stored here.',self::DOMAIN) : esc_html__('Notification: pending or interrupted; delivery unconfirmed.',self::DOMAIN)); ?></p></details></td><td><?php echo esc_html(get_date_from_gmt($r['created_at'],get_option('date_format'))); ?><small><?php echo esc_html(get_date_from_gmt($r['created_at'],get_option('time_format'))); ?></small></td><td><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="fcb_inbox"><input type="hidden" name="mode" value="status"><input type="hidden" name="id" value="<?php echo (int)$r['id']; ?>"><?php wp_nonce_field('fcb_inbox'); ?><label class="screen-reader-text" for="fcb-status-<?php echo (int)$r['id']; ?>"><?php esc_html_e('Follow-up status',self::DOMAIN); ?></label><select id="fcb-status-<?php echo (int)$r['id']; ?>" name="status"><?php foreach (['new'=>__('New',self::DOMAIN),'contacted'=>__('Contacted',self::DOMAIN),'resolved'=>__('Resolved',self::DOMAIN)] as $key=>$label) { echo '<option value="'.esc_attr($key).'" '.selected($r['status'],$key,false).'>'.esc_html($label).'</option>'; } ?></select><button class="fcb-button fcb-button-light fcb-small"><?php esc_html_e('Update status',self::DOMAIN); ?></button></form></td><td><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="fcb_inbox"><input type="hidden" name="mode" value="delete"><input type="hidden" name="id" value="<?php echo (int)$r['id']; ?>"><?php wp_nonce_field('fcb_inbox'); ?><button class="fcb-delete" type="submit" data-confirm="<?php esc_attr_e('Delete this enquiry permanently?',self::DOMAIN); ?>"><?php esc_html_e('Delete',self::DOMAIN); ?></button></form></td></tr><?php endforeach; ?>
</tbody></table></div>
<nav class="fcb-pagination" aria-label="<?php esc_attr_e('Enquiry pages',self::DOMAIN); ?>"><?php echo wp_kses_post(paginate_links(['base'=>add_query_arg('paged','%#%'),'format'=>'','total'=>max(1,ceil($records['total']/25)),'current'=>$current])); ?></nav><?php endif; ?>
</section>
<section class="fcb-card-admin fcb-danger-zone"><h2><?php esc_html_e('Delete stored enquiries',self::DOMAIN); ?></h2><p><?php esc_html_e('This permanently removes all locally stored requests, including unresolved ones. Email copies are unaffected.',self::DOMAIN); ?></p><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="fcb_inbox"><input type="hidden" name="mode" value="delete_all"><?php wp_nonce_field('fcb_inbox'); ?><label><input type="checkbox" name="confirm_delete" value="yes" required> <?php esc_html_e('I understand that all stored enquiries will be deleted.',self::DOMAIN); ?></label><button class="fcb-button fcb-button-danger" type="submit"><?php esc_html_e('Delete all enquiries',self::DOMAIN); ?></button></form></section>
